namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and leads the university's AI Research Lab.", Email = "a.chen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on software engineering and distributed systems. He spent 10 years in industry at major tech companies before joining academia.", Email = "r.martinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Bio = "Dr. Johnson is an expert in abstract algebra and number theory. She is a recipient of the National Science Foundation CAREER Award.", Email = "s.johnson@university.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Associate Professor of Physics", Bio = "Dr. Wilson researches quantum mechanics and particle physics. He collaborates with CERN on large-scale experiments.", Email = "j.wilson@university.edu" },
            new() { Id = 5, Name = "Prof. Emily Davis", Title = "Professor of English", Bio = "Prof. Davis is a published novelist and literary critic specializing in contemporary American fiction and creative writing.", Email = "e.davis@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor of History", Bio = "Dr. Brown studies modern European history with a focus on 20th-century political movements and their cultural impact.", Email = "m.brown@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Includes complexity analysis and practical problem-solving.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 3, Code = "CS 301", Title = "Database Systems", Description = "Introduction to relational database design, SQL, normalization, indexing, and transaction management. Includes a semester-long project building a complete database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 4, Code = "CS 401", Title = "Artificial Intelligence", Description = "Survey of AI techniques including search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Essential for computer science, physics, and engineering students.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world applications.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 9, Code = "PHYS 201", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS 101, MATH 201.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop effective academic writing skills. Focus on argumentation, research methods, and clear prose style.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 11, Code = "ENG 205", Title = "Creative Writing Workshop", Description = "Workshop-based course in fiction and poetry. Students produce original work and participate in peer critique sessions.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = true },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations from antiquity through the late medieval period. Examines political, cultural, and economic developments.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = false },
            new() { Id = 13, Code = "HIST 301", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Topics include nationalism, industrialization, world wars, and the European Union.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = false },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

